insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('double_next_rewards', 'Take a Shot to Double Next Question Rewards', 'drink', 'next_question_modifier', 'Take a shot to double the rewards from the next question.', '{"reward_multiplier":2,"cost":"shot"}'::jsonb, null, null, 2, 11, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('cheers', 'Cheers', 'drink', 'text', 'One team member from each team must drink asap.', '{}'::jsonb, null, null, 2, 12, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('drinks_all_round', 'Drinks All Round', 'drink', 'text', 'Everyone on both teams must drink asap.', '{}'::jsonb, null, null, 1, 13, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('distant_cuisine', 'Curse of Distant Cuisine', 'curse', 'until_cleared', 'Find a restaurant within your zone that serves food from a specific foreign country. The seekers must visit a restaurant serving food from a country that is a greater distance away before asking their next question.', '{"blocks_questions":true}'::jsonb, 'free', true, 1, 14, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('unguided_tourist', 'Curse of Unguided Tourist', 'curse', 'until_cleared', 'Send the seekers an unzoomed Google Street View image from a street within 150 m of where they are now. The shot has to be parallel to the horizon and include at least one human-built structure other than a road. Without using the internet for research, they must find what you sent them in real life before asking another question. They must send a picture to the hider for verification.', '{"blocks_questions":true,"proof":"photo","radius_m":150}'::jsonb, 'free', true, 1, 15, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('bird_guide', 'Curse of Bird Guide', 'curse', 'until_cleared', 'You have one chance to film a bird for as long as possible, up to 5 minutes straight. If, at any point, the bird leaves the frame, the timer is stopped. The seekers must then film a bird for the same amount of time or longer before asking another question.', '{"blocks_questions":true,"proof":"video","max_s":300}'::jsonb, 'free', true, 1, 16, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('luxury_car', 'Curse of Luxury Car', 'curse', 'until_cleared', 'Take a photo of a car. The seekers must take a photo of a more expensive car before asking another question.', '{"blocks_questions":true,"proof":"photo"}'::jsonb, 'free', true, 1, 17, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('bridge', 'Curse of Bridge', 'curse', 'until_cleared', 'The seekers must ask their next question from under a bridge.', '{"blocks_questions":true}'::jsonb, 'drink', true, 1, 18, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('right_turn', 'Curse of Right Turn', 'curse', 'timed', 'For the next 20 minutes, the seekers can only turn right at any street intersection. If at any point they find themselves in a dead end where they cannot continue, they may do a full 180.', '{"duration_s":1200}'::jsonb, 'drink', true, 1, 19, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('jammed_door', 'Curse of Jammed Door', 'curse', 'timed', 'For the next 30 minutes, whenever the seekers want to pass through a doorway into a building, they must roll two dice. If they don''t roll above a 7, they cannot enter that space. Each doorway can be re-attempted after 5 minutes.', '{"duration_s":1800,"utility":"dice","dice":2,"retry_s":300}'::jsonb, 'shot', true, 1, 20, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('u_turn', 'Curse of U-Turn', 'curse', 'text', 'The seekers must disembark their current mode of transportation at the next station (as long as that station is serviced by another form of transit in the next 30 minutes).', '{"window_s":1800}'::jsonb, 'shot', false, 1, 21, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('drained_brain', 'Curse of Drained Brain', 'curse', 'question_ban', 'Choose three questions in different categories. The seekers cannot ask those questions for the rest of the run.', '{"count":3,"distinct_types":true,"until":"end_of_run"}'::jsonb, 'shot', false, 1, 22, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('express_route', 'Curse of Express Route', 'curse', 'timed', 'Seekers can''t disembark transport for 5 minutes.', '{"duration_s":300}'::jsonb, 'shot', false, 1, 23, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('menu', 'Curse of Menu', 'curse', 'until_cleared', 'Hiders must pick a drink from their bar menu (any branded alcohol). Seekers need to find the same one and drink it before asking another question.', '{"blocks_questions":true,"proof":"photo"}'::jsonb, 'free', true, 1, 24, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('prison', 'Curse of Prison', 'curse', 'timed', 'If seekers are in your chosen hiding bar when this is played, they are locked there for 10 minutes and draw a card. You must tell them they are at your bar.', '{"duration_s":600,"condition":"seekers_in_hider_bar"}'::jsonb, 'free', false, 1, 25, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('pokies', 'Curse of Pokies', 'curse', 'until_cleared', 'Seekers cannot ask any more questions until successfully winning the pokies.', '{"blocks_questions":true}'::jsonb, 'drink', true, 1, 26, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('clash', 'Curse of Clash', 'curse', 'until_cleared', 'Seekers can''t use any transport until beating the hiders at Clash Royale.', '{"blocks_questions":false,"blocks":"transport"}'::jsonb, 'drink', true, 1, 27, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('sculling', 'Curse of Sculling', 'curse', 'until_cleared', 'Hiders get one chance to chug a schooner / pint and time it. Seekers can''t use transport until they are able to chug a schooner / pint quicker.', '{"blocks_questions":false,"blocks":"transport"}'::jsonb, 'drink', true, 1, 28, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('escape', 'Curse of Escape', 'curse', 'timed', 'Seekers have 3 minutes to exit a bar. Any drinks ordered must be finished before they can leave. If they don''t leave in time, they are locked in the bar for 10 minutes.', '{"duration_s":180,"followup_s":600}'::jsonb, 'drink', false, 1, 29, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('impression', 'Curse of Impression', 'curse', 'until_cleared', 'Seekers must spin the impression wheel. They cannot ask any more questions until a stranger guesses their character correctly.', '{"blocks_questions":true,"utility":"wheel","wheel_url":"https://wheelofnames.com/wf2-fd2"}'::jsonb, 'shot', true, 1, 30, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('hammered', 'Curse of Hammered', 'curse', 'until_cleared', 'Seekers roll a die. The number indicates the amount of shots they must drink before asking another question. Shots can be distributed across team members.', '{"blocks_questions":true,"utility":"dice","dice":1}'::jsonb, 'shot', false, 1, 31, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('quan', 'Curse of Quan', 'curse', 'until_cleared', 'Seekers must lose a game of pool before asking their next question.', '{"blocks_questions":true}'::jsonb, 'shot', true, 1, 32, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('moll', 'Curse of Moll', 'curse', 'until_cleared', 'Seekers must correctly answer 3 Harry Potter trivia questions before using transport. No Googling.', '{"blocks_questions":false,"blocks":"transport"}'::jsonb, 'drink', true, 1, 33, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('louis', 'Curse of Louis', 'curse', 'until_cleared', 'Seekers must ask their next question from inside a Chinese restaurant, or from Chinatown in the Valley.', '{"blocks_questions":true}'::jsonb, 'drink', true, 1, 34, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('cruz', 'Curse of Cruz', 'curse', 'until_cleared', 'Seekers must ask their next question from inside a KFC, or after eating something watermelon flavoured.', '{"blocks_questions":true}'::jsonb, 'shot', true, 1, 35, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('nathan', 'Curse of Nathan', 'curse', 'text', null, '{"todo":"No text yet; copies set to 0 so it stays out of the deck"}'::jsonb, null, true, 0, 36, true) on conflict (id) do nothing;
insert into public.cards (id, name, category_id, behaviour, body, params, cast_cost, can_veto, default_copies, sort, active) values ('brothel', 'Curse of Brothel', 'curse', 'text', 'The seeking team must take a shot for every 3 people in VC on the Discord at the time this card is played. @ing people to join beforehand is allowed, but the hiders can also disconnect people.', '{"todo":"Idea card, not in the first-game deck; set copies above 0 to use it"}'::jsonb, 'shot', false, 0, 37, true) on conflict (id) do nothing;
